#include "Code/wxCharacterTraits.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>

using Traits = winx::reconstruction::wxCharacterTraits;
using Prefix = Traits::CapturedPrefixForAnalysis;
using Profile = Traits::PropertyProfileForAnalysis;
using Result = Traits::PropertyResultForAnalysis;
namespace
{
    unsigned checks = 0;
    bool Check(const bool value) { ++checks; if (!value) std::cerr << "CharacterTraitsProperty contract " << checks << " failed\n"; return value; }
    int Digit(const char value) { if (value >= '0' && value <= '9') return value - '0'; if (value >= 'a' && value <= 'f') return value - 'a' + 10; if (value >= 'A' && value <= 'F') return value - 'A' + 10; return -1; }
    bool Decode(const std::string& text, Prefix& output)
    {
        if (text.size() != output.size() * 2) return false;
        for (std::size_t i = 0; i != output.size(); ++i) { const auto high = Digit(text[i * 2]), low = Digit(text[i * 2 + 1]); if (high < 0 || low < 0) return false; output[i] = static_cast<std::uint8_t>(high * 16 + low); }
        return true;
    }
    bool DecodeWord(const std::string& text, std::uint32_t& output)
    {
        if (text.size() != 8) return false;
        std::uint32_t staged = 0;
        for (const auto byte : text) { const auto value = Digit(byte); if (value < 0) return false; staged = (staged << 4) | static_cast<std::uint32_t>(value); }
        output = staged; return true;
    }
    std::string Encode(const Prefix& input) { constexpr char digits[] = "0123456789abcdef"; std::string text; for (const auto byte : input) { text += digits[byte >> 4]; text += digits[byte & 15]; } return text; }
    std::string EncodeWord(const std::uint32_t input) { constexpr char digits[] = "0123456789abcdef"; std::string text; for (int shift = 28; shift >= 0; shift -= 4) text += digits[(input >> shift) & 15]; return text; }
    struct Example { const char* input; std::uint32_t value; const char* expected; };
    const std::array<Example, 16> examples{{
        {"", 0x00000000u, ""},
        {"", 0x00000001u, ""},
        {"", 0x7FFFFFFFu, ""},
        {"", 0x80000000u, ""},
        {"", 0xFFFFFFFFu, ""},
        {"", 0x55555555u, ""},
        {"", 0xAAAAAAAAu, ""},
        {"", 0x00000100u, ""},
        {"", 0x01000000u, ""},
        {"", 0x01020304u, ""},
        {"", 0xFF0000FFu, ""},
        {"", 0x0000FFFFu, ""},
        {"", 0xFFFF0000u, ""},
        {"", 0x80000001u, ""},
        {"", 0xDEADBEEFu, ""},
        {"", 0x7F800001u, ""}
    }};
    bool Contracts()
    {
        bool passed = true;
        for (const auto& example : examples)
        {
            Prefix before{}, expected{}, output{};
            passed = Check(Decode(example.input, before) && Decode(example.expected, expected)) && passed;
            const auto original = before;
            std::uint32_t old = 0, after = 0;
            passed = Check(Traits::ReadValueOfFairyStarsRawForAnalysis(before, old, Profile::PcCapturedPrimaryRaw1A4) == Result::Completed) && passed;
            const auto initial = std::uint32_t(before[0x1A4]) | (std::uint32_t(before[0x1A5]) << 8) | (std::uint32_t(before[0x1A6]) << 16) | (std::uint32_t(before[0x1A7]) << 24);
            passed = Check(old == initial) && passed;
            passed = Check(Traits::WriteValueOfFairyStarsRawForAnalysis(before, example.value, output, Profile::PcCapturedPrimaryRaw1A4) == Result::Completed) && passed;
            passed = Check(output == expected && before == original) && passed;
            passed = Check(Traits::ReadValueOfFairyStarsRawForAnalysis(output, after, Profile::PcCapturedPrimaryRaw1A4) == Result::Completed && after == example.value) && passed;
            auto alias = before;
            passed = Check(Traits::WriteValueOfFairyStarsRawForAnalysis(alias, example.value, alias, Profile::PcCapturedPrimaryRaw1A4) == Result::Completed && alias == expected) && passed;
            passed = Check(Traits::WriteValueOfFairyStarsRawForAnalysis(alias, example.value, alias, Profile::PcCapturedPrimaryRaw1A4) == Result::Completed && alias == expected) && passed;
            output.fill(0x5C); const auto refused = output; after = 0x13579BDF;
            passed = Check(Traits::WriteValueOfFairyStarsRawForAnalysis(before, example.value, output) == Result::UnqualifiedProfile && output == refused) && passed;
            passed = Check(Traits::ReadValueOfFairyStarsRawForAnalysis(before, after) == Result::UnqualifiedProfile && after == 0x13579BDF) && passed;
        }
        Prefix foreign{}, output{}; output.fill(0x5C); const auto refused = output; std::uint32_t value = 0x13579BDF;
        passed = Check(Traits::WriteValueOfFairyStarsRawForAnalysis(foreign, 1, output, Profile::PcCapturedPrimaryRaw1A4) == Result::CapturedPrimaryNotAdmitted && output == refused) && passed;
        passed = Check(Traits::ReadValueOfFairyStarsRawForAnalysis(foreign, value, Profile::PcCapturedPrimaryRaw1A4) == Result::CapturedPrimaryNotAdmitted && value == 0x13579BDF) && passed;
        return passed;
    }
}
int main(const int argc, char** argv)
{
    if (argc == 2 && std::string(argv[1]) == "--replay")
    {
        std::string line;
        while (std::getline(std::cin, line))
        {
            std::istringstream stream(line); std::string bytes, word, extra; Prefix before{}, output{}; std::uint32_t value = 0, old = 0, after = 0;
            if (!(stream >> bytes >> word) || (stream >> extra) || !Decode(bytes, before) || !DecodeWord(word, value)
                || Traits::ReadValueOfFairyStarsRawForAnalysis(before, old, Profile::PcCapturedPrimaryRaw1A4) != Result::Completed
                || Traits::WriteValueOfFairyStarsRawForAnalysis(before, value, output, Profile::PcCapturedPrimaryRaw1A4) != Result::Completed
                || Traits::ReadValueOfFairyStarsRawForAnalysis(output, after, Profile::PcCapturedPrimaryRaw1A4) != Result::Completed) std::cout << "REFUSED\n";
            else std::cout << EncodeWord(old) << ' ' << Encode(output) << ' ' << EncodeWord(after) << '\n';
        }
        return 0;
    }
    if (!Contracts()) return 1;
    std::cout << "CharacterTraitsProperty: " << checks << " contracts passed\n";
    return 0;
}
